// Typed view of bridge/data/mapping.json (generated by tools/data/build_mapping.js).
// Only the sections the resolver ports read are modelled; System.Text.Json ignores the rest. Keys are snake_case in the file.
using System.Text.Json.Serialization;

namespace CK3xBL.Mapping.Data;

public sealed class MappingJson
{
    public string DefaultCulture { get; set; } = "empire";
    public string DefaultProfile { get; set; } = "default";

    // Culture -> profile resolution.
    public Dictionary<string, string> CultureProfileMap { get; set; } = new();
    public Dictionary<string, HeritageGfxOverride> HeritageGfxOverrides { get; set; } = new();
    public Dictionary<string, string> HeritageProfileMap { get; set; } = new();
    public Dictionary<string, string> UnitGfxProfileMap { get; set; } = new();
    public Dictionary<string, Profile> Profiles { get; set; } = new();

    // Levies: era -> levy variant -> flattened troop mix.
    public Dictionary<string, Dictionary<string, List<TroopWeight>>> LevyByEra { get; set; } = new();

    // Men-at-arms.
    public TierRule TierRule { get; set; } = new();
    public Dictionary<string, BaseRole> BaseRoles { get; set; } = new();
    public Dictionary<string, Dictionary<string, List<Rung>>> MaaLadders { get; set; } = new();
    public Dictionary<string, List<Rung>> SharedLadders { get; set; } = new();
    public Dictionary<string, MaaTierInfo> MaaTier { get; set; } = new();
    public Dictionary<string, MaaOverride> MaaOverrides { get; set; } = new();

    // Knights and commanders.
    public Dictionary<string, List<TroopWeight>> Knights { get; set; } = new();
    public Dictionary<string, CommanderBodies> Commanders { get; set; } = new();
    public CommanderRules CommanderRules { get; set; } = new();

    // Casualties and winter.
    public CasualtyTables Casualties { get; set; } = new();
    public WinterState WinterState { get; set; } = new();

    // v0 climate model; only used when a province is missing from ck3_province_climate.json.
    public List<ClimateRegion> ClimateRegions { get; set; } = new();
    public string ClimateDefault { get; set; } = "temperate";
    public Dictionary<string, string> TerrainDefaultClimate { get; set; } = new();

    // Troop lines allowed only in their own setting; validated by MappingTables.Load (TroopRestrictions).
    public RestrictedTroopsJson? RestrictedTroops { get; set; }
}

public sealed class TroopWeight
{
    public string Troop { get; set; } = "";
    public double Weight { get; set; }
}

/// <summary>One rung of a troop ladder: the troop mix that stands for a (possibly fractional) Bannerlord tier.</summary>
public sealed class Rung
{
    public double Tier { get; set; }
    public List<TroopWeight> Troops { get; set; } = new();
}

/// <summary>Entries gated by CK3 culture era (min_era / max_era, both inclusive).</summary>
public interface IEraGated
{
    string? MinEra { get; }
    string? MaxEra { get; }
}

public sealed class HeritageGfxOverride
{
    public string Profile { get; set; } = "";
}

public sealed class Profile
{
    public string BlCulture { get; set; } = "empire";
    public string? LevyVariant { get; set; }
    public Dictionary<string, List<RoleOverride>>? RoleOverrides { get; set; }
    public List<EraTroops>? Knights { get; set; }
}

public sealed class RoleOverride : IEraGated
{
    public string? MinEra { get; set; }
    public string? MaxEra { get; set; }
    public List<Rung>? Ladder { get; set; }
    public string? UseCulture { get; set; }
}

public sealed class EraTroops : IEraGated
{
    public string? MinEra { get; set; }
    public string? MaxEra { get; set; }
    public List<TroopWeight> Troops { get; set; } = new();
}

public sealed class TierRule
{
    [JsonPropertyName("terrain_delta_clamp")]
    public List<double>? TerrainDeltaClamp { get; set; }
}

public sealed class BaseRole
{
    public string? Role { get; set; }
    /// <summary>The regular CK3 MaA of this base type whose damage and toughness the tier rule measures against.</summary>
    public string? RefMaa { get; set; }
    public double RefTier { get; set; }
    public string? LadderRef { get; set; }
    public string? ForceCulture { get; set; }
    public bool Exclude { get; set; }
    public string? Note { get; set; }
}

public sealed class MaaTierInfo
{
    public string BaseType { get; set; } = "";
    public bool Excluded { get; set; }
    public double Toughness { get; set; }
    public double TierTarget { get; set; }
    public Dictionary<string, double>? TerrainTierDelta { get; set; }
    public Dictionary<string, double>? WinterTierDelta { get; set; }
}

public sealed class MaaOverride
{
    public double? TierTarget { get; set; }
    public string? LadderRole { get; set; }
    public string? LadderRef { get; set; }
    public string? ForceCulture { get; set; }
}

public sealed class CommanderBody
{
    public string Character { get; set; } = "";
}

public sealed class CommanderBodies
{
    public List<CommanderBody> MaleMounted { get; set; } = new();
    public List<CommanderBody> MaleFoot { get; set; } = new();
    public List<CommanderBody> Female { get; set; } = new();
}

public sealed class CommanderRules
{
    public Dictionary<string, string> FemaleFallback { get; set; } = new();
}

public sealed class CasualtyTables
{
    public FatalRatioModifiers FatalRatioModifiers { get; set; } = new();
}

public sealed class FatalRatioModifiers
{
    public Dictionary<string, TerrainCasualtyModifiers> Terrain { get; set; } = new();
}

public sealed class TerrainCasualtyModifiers
{
    public Dictionary<string, double> Attacker { get; set; } = new();
    public Dictionary<string, double> Defender { get; set; } = new();
}

public sealed class WinterState
{
    public Dictionary<string, string> MaaWinterKey { get; set; } = new();
}

public sealed class ClimateRegion
{
    public string Region { get; set; } = "";
    public string Climate { get; set; } = "";
}
